 14	@Repository
 15	public class OrderRepository {
 16	
 17	    private static final String SELECT = "SELECT * FROM orders WHERE id = :id";
 18	
 19	    private final JdbcClient jdbc;
 20	
 21	    public OrderRepository(JdbcClient jdbc) {
 22	        this.jdbc = jdbc;
 23	    }
 24	
 25	    public void insert(String cpf, String email, Order order) {
 26	        OrderSummary s = order.summary();
 27	        jdbc.sql("""
 28	                INSERT INTO orders (id, cpf, email, status, created_at, tracking_code, products_subtotal,
 29	                  coupon_discount, shipping_cost, delivery_days, insurance, payment_adjustment, final_total,
 30	                  installments, installment_amount, next_purchase_credit, gift)
 31	                VALUES (:id, :cpf, :email, :status, :createdAt, NULL, :subtotal, :discount, :shipping, :days,
 32	                  :insurance, :adjustment, :total, :installments, :installmentAmount, :credit, :gift)
 33	                """)
 34	                .param("id", order.id()).param("cpf", cpf).param("email", email)
 35	                .param("status", order.status().name())
 36	                .param("createdAt", OffsetDateTime.ofInstant(order.createdAt(), ZoneOffset.UTC))
 37	                .param("subtotal", s.productsSubtotal()).param("discount", s.couponDiscount())
 38	                .param("shipping", s.shippingCost()).param("days", s.deliveryDays())
 39	                .param("insurance", s.insurance()).param("adjustment", s.paymentAdjustment())
 40	                .param("total", s.finalTotal()).param("installments", s.installments())
 41	                .param("installmentAmount", s.installmentAmount()).param("credit", s.nextPurchaseCredit())
 42	                .param("gift", s.gift()).update();
 43	        int position = 0;
 44	        for (Order.Item item : order.items()) {
 45	            jdbc.sql("INSERT INTO order_items (order_id, position, sku, quantity) VALUES (:id, :pos, :sku, :q)")
 46	                    .param("id", order.id()).param("pos", position++).param("sku", item.sku())
 47	                    .param("q", item.quantity()).update();
 48	        }
 49	    }
 50	
 51	    public Optional<StoredOrder> find(String id) {
 52	        return jdbc.sql(SELECT).param("id", id).query(this::map).optional().map(this::withItems);
 53	    }
 54	
 55	    /** Reads the order locking its row until the end of the transaction. */
 56	    public Optional<StoredOrder> findForUpdate(String id) {
 57	        return jdbc.sql(SELECT + " FOR UPDATE").param("id", id).query(this::map).optional().map(this::withItems);
 58	    }
