 60	    public void updateStatus(String id, OrderStatus status) {
 61	        jdbc.sql("UPDATE orders SET status = :s WHERE id = :id").param("s", status.name()).param("id", id).update();
 62	    }
 63	
 64	    public void updateShipment(String id, String trackingCode) {
 65	        jdbc.sql("UPDATE orders SET status = :s, tracking_code = :t WHERE id = :id")
 66	                .param("s", OrderStatus.SHIPPED.name()).param("t", trackingCode).param("id", id).update();
 67	    }
 68	
 69	    /** Whether the customer has an order that was paid, shipped or delivered. */
 70	    public boolean hasPaidOrder(String cpf) {
 71	        return jdbc.sql("SELECT COUNT(*) FROM orders WHERE cpf = :cpf AND status IN ('PAID', 'SHIPPED', 'DELIVERED')")
 72	                .param("cpf", cpf).query(Long.class).single() > 0;
 73	    }
 74	
 75	    public Optional<String> findPaymentOutcome(String orderId, String transactionId) {
 76	        return jdbc.sql("SELECT outcome FROM payment_events WHERE order_id = :o AND transaction_id = :t")
 77	                .param("o", orderId).param("t", transactionId).query(String.class).optional();
 78	    }
 79	
 80	    public void recordPaymentOutcome(String orderId, String transactionId, String outcome) {
 81	        jdbc.sql("INSERT INTO payment_events (order_id, transaction_id, outcome) VALUES (:o, :t, :out)")
 82	                .param("o", orderId).param("t", transactionId).param("out", outcome).update();
 83	    }
 84	
 85	    private StoredOrder withItems(StoredOrder stored) {
 86	        Order o = stored.order();
 87	        List<Order.Item> items = jdbc.sql("SELECT sku, quantity FROM order_items WHERE order_id = :id ORDER BY position")
 88	                .param("id", o.id()).query((rs, n) -> new Order.Item(rs.getString("sku"), rs.getInt("quantity")))
 89	                .list();
 90	        return new StoredOrder(stored.cpf(), new Order(o.id(), o.status(), o.createdAt(), o.summary(), items,
 91	                o.trackingCode()));
 92	    }
 93	
 94	    private StoredOrder map(ResultSet rs, int row) throws SQLException {
 95	        OrderSummary summary = new OrderSummary(money(rs, "products_subtotal"), money(rs, "coupon_discount"),
 96	                money(rs, "shipping_cost"), rs.getInt("delivery_days"), money(rs, "insurance"),
 97	                money(rs, "payment_adjustment"), money(rs, "final_total"), rs.getInt("installments"),
 98	                money(rs, "installment_amount"), money(rs, "next_purchase_credit"), rs.getBoolean("gift"));
 99	        Instant createdAt = rs.getObject("created_at", OffsetDateTime.class).toInstant();
100	        Order order = new Order(rs.getString("id"), OrderStatus.valueOf(rs.getString("status")), createdAt, summary,
101	                List.of(), rs.getString("tracking_code"));
102	        return new StoredOrder(rs.getString("cpf"), order);
103	    }
104	
105	    private static java.math.BigDecimal money(ResultSet rs, String column) throws SQLException {
106	        return rs.getBigDecimal(column).setScale(2);
107	    }
108	}
