131	        try {
132	            jdbc.sql("INSERT INTO customers (cpf, email, credit_balance) "
133	                    + "SELECT :cpf, :email, 0 WHERE NOT EXISTS (SELECT 1 FROM customers WHERE cpf = :cpf)")
134	                    .param("cpf", cpf).param("email", email).update();
135	        } catch (DuplicateKeyException e) {
136	            // created concurrently by another request
137	        }
