178	    public List<Product> findAll(Collection<String> skus) {
179	        if (skus.isEmpty()) {
180	            return List.of();
181	        }
182	        return jdbc.sql("SELECT " + COLUMNS + " FROM products WHERE sku IN (:skus)")
183	                .param("skus", skus).query(this::map).list();
184	    }
185	
186	    /** Locks the product row until the end of the transaction and returns its current stock. */
187	    public int lockStock(String sku) {
188	        return jdbc.sql("SELECT stock FROM products WHERE sku = :sku FOR UPDATE")
189	                .param("sku", sku).query(Integer.class).single();
190	    }
191	
192	    public void decrementStock(String sku, int quantity) {
193	        int updated = jdbc.sql("UPDATE products SET stock = stock - :q WHERE sku = :sku AND stock >= :q")
194	                .param("q", quantity).param("sku", sku).update();
195	        if (updated != 1) {
196	            throw new IllegalStateException("stock would become negative for " + sku);
197	        }
198	    }
199	
200	    public void incrementStock(String sku, int quantity) {
201	        jdbc.sql("UPDATE products SET stock = stock + :q WHERE sku = :sku")
202	                .param("q", quantity).param("sku", sku).update();
203	    }
204	
205	    private Product map(ResultSet rs, int row) throws SQLException {
206	        BigDecimal weight = rs.getBigDecimal("weight_kg").stripTrailingZeros();
207	        if (weight.scale() < 2) {
208	            weight = weight.setScale(2);
209	        }
210	        return new Product(rs.getString("sku"), rs.getString("name"), rs.getBigDecimal("price").setScale(2),
211	                weight, rs.getInt("stock"), rs.getBoolean("discontinued"));
212	    }
213	}
